SELECT dm.status, COUNT(1) count FROM device_manage dm left join market_config mc on mc.market_tenant = dm.market_tenant
inner join safety_app_device sad on sad.id = dm.id
mc.status = true
AND dm.market_tenant IN
#{id}
AND dm.create_time BETWEEN #{baseQuery.createdPeriod.begin} AND #{baseQuery.createdPeriod.end}
AND sad.application_code IN
#{code}
GROUP BY dm.status

select
dm.*
from device_manage dm
left join market_config mc on mc.market_tenant = dm.market_tenant

    inner join safety_app_device sad on sad.id = dm.id


    mc.status = true

        and dm.create_time >= #{query.period.begin} and dm.create_time < #{query.period.end}


        and dm.market_tenant = #{query.marketTenant}


        AND sad.application_code IN

            #{code}

select
dm.*
from device_manage dm
left join market_config mc on mc.market_tenant = dm.market_tenant

    inner join safety_app_device sad on sad.id = dm.id


    mc.status = true

        and dm.create_time >= #{query.period.begin} and dm.create_time < #{query.period.end}


        and dm.market_tenant = #{query.marketTenant}


