select dm.iot_device_prod_category_name as `name`, count(DISTINCT dm.id) as `count` from device_manage dm left join market_config mc on mc.market_tenant = dm.market_tenant
inner join safety_app_device sad on sad.id = dm.id
mc.status = true
and dm.create_time >= #{query.period.begin} and dm.create_time < #{query.period.end}
and dm.market_tenant = #{query.marketTenant}
AND sad.application_code IN
#{code}
group by dm.iot_device_prod_category_name
